(() => {
  const result = $json;
  const findings = Array.isArray(result.findings) ? result.findings : [];

  const confirmed = findings.filter(f => f.confirmed === true);
  const unconfirmed = findings.filter(f => f.confirmed !== true);

  let md = '## 🔐 Security Analysis\n\n';

  if (confirmed.length === 0) {
    md += '### ✅ No confirmed vulnerabilities\n\n';
    md += 'The security analyzer did not confirm any genuine security vulnerabilities in the detected changes.\n';
  } else {
    md += `### 🚨 Confirmed vulnerabilities (${confirmed.length})\n\n`;

    confirmed.forEach((f, i) => {
      md += `#### ${i + 1}. ${f.title || f.vulnerability || 'Security vulnerability'}\n\n`;
      md += `- **Vulnerability:** ${f.vulnerability || 'Unknown'}\n`;
      md += `- **Severity:** ${f.severity || 'Unknown'}\n`;
      md += `- **Confidence:** ${f.confidence || 'Unknown'}\n`;
      md += `- **File:** \`${f.file || 'Unknown'}\`\n`;
      md += `- **Line:** \`${f.line || 'Unknown'}\`\n\n`;

      md += `**Description**\n\n${f.description || 'No description provided.'}\n\n`;

      if (f.evidence) {
        md += `**Evidence**\n\n${f.evidence}\n\n`;
      }

      if (f.attackScenario) {
        md += `**Attack Scenario**\n\n${f.attackScenario}\n\n`;
      }

      if (f.recommendation) {
        md += `**Recommendation**\n\n${f.recommendation}\n\n`;
      }

      md += '---\n\n';
    });
  }

  if (unconfirmed.length > 0) {
    md += `### ℹ️ Unconfirmed findings (${unconfirmed.length})\n\n`;
    md += 'These findings were reviewed but the supplied changes did not provide enough evidence to confirm an exploitable vulnerability.\n\n';

    unconfirmed.forEach((f, i) => {
      md += `#### ${i + 1}. ${f.title || f.vulnerability || 'Security concern'}\n\n`;
      md += `- **Vulnerability:** ${f.vulnerability || 'Unknown'}\n`;
      md += `- **Severity:** ${f.severity || 'Unknown'}\n`;
      md += `- **Confidence:** ${f.confidence || 'Unknown'}\n`;
      md += `- **File:** \`${f.file || 'Unknown'}\`\n`;
      md += `- **Line:** \`${f.line || 'Unknown'}\`\n\n`;

      md += `**Analysis**\n\n${f.description || 'No analysis provided.'}\n\n`;

      if (f.evidence) {
        md += `**Evidence**\n\n${f.evidence}\n\n`;
      }

      if (f.recommendation) {
        md += `**Recommendation**\n\n${f.recommendation}\n\n`;
      }

      md += '---\n\n';
    });
  }

  return md;
})()
}}

